namespace core = "urn:eigenius:core";
namespace patent = "urn:eigenius:demo:patent";
namespace completion = "urn:eigenius:program:components:completion";
namespace request = "urn:eigenius:program:request";

// --- Input type ---

class patent:PatentClaim {
    description = "A patent claim or abstract to be analyzed.";
    requires patent:title, patent:patent_number, patent:abstract_text;
    recommends patent:assignee, patent:filing_date;
}

property patent:title : core:string {
    description = "Title of the patent.";
}

property patent:patent_number : core:string {
    description = "Patent number (e.g., US6285999B1).";
}

property patent:abstract_text : core:string {
    description = "The abstract or claim text of the patent.";
}

property patent:assignee : core:string {
    description = "The assignee or applicant of the patent.";
}

property patent:filing_date : core:string {
    description = "Filing date of the patent.";
}

// --- Structured analysis (CompleteJson output) ---

class patent:PatentAnalysis {
    description = "Structured analysis extracted from a patent claim.";
    requires patent:invention_category, patent:technical_domain, patent:key_innovations, patent:practical_applications;
    recommends patent:prior_art_references, patent:limitations;
}

property patent:invention_category : core:string {
    description = "Category of the invention (e.g., method, system, apparatus, composition).";
}

property patent:technical_domain : core:string {
    description = "The technical domain or field of the invention.";
}

property patent:key_innovations : core:value_array {
    description = "List of key innovations or novel aspects claimed.";
    element_type = core:string;
}

property patent:practical_applications : core:value_array {
    description = "Practical applications or use cases of the invention.";
    element_type = core:string;
}

property patent:prior_art_references : core:value_array {
    description = "References to prior art or related technologies mentioned.";
    element_type = core:string;
}

property patent:limitations : core:value_array {
    description = "Noted limitations or constraints of the invention.";
    element_type = core:string;
}

// --- Final output (CompleteText narrative + structured analysis) ---

class patent:PatentBrief {
    description = "A patent brief combining structured analysis with a plain-language summary.";
    requires patent:summary, patent:analysis;
}

property patent:summary : core:string {
    description = "A plain-language technical summary suitable for a non-specialist audience.";
}

property patent:analysis : core:resource {
    description = "The structured patent analysis.";
    class_types patent:PatentAnalysis;
}

// --- Pipeline ---

program patent:analyze_patent : patent:PatentClaim -> patent:PatentBrief {
    let analysis : patent:PatentAnalysis = CompleteJson(input) {
        completion:user_prompt = "Analyze this patent and extract structured information.\n\nTitle: {{urn:eigenius:demo:patent:title}}\nPatent Number: {{urn:eigenius:demo:patent:patent_number}}\n\nAbstract:\n{{urn:eigenius:demo:patent:abstract_text}}";
        completion:system_prompt = "You are a patent analyst. Extract the invention category, technical domain, key innovations, practical applications, prior art references, and limitations from the patent text. Be precise and technical.";
        completion:output_schema = patent:PatentAnalysis;
        completion:request_parameters = {
            request:model = "claude-sonnet-4-6";
            request:temperature = 0.0;
            request:max_tokens = 2000;
        };
    };
    let summary : core:string = CompleteText(analysis) {
        completion:user_prompt = "Based on this patent analysis, write a 2-3 paragraph plain-language technical summary suitable for a non-specialist decision-maker.\n\nCategory: {{urn:eigenius:demo:patent:invention_category}}\nDomain: {{urn:eigenius:demo:patent:technical_domain}}\nKey Innovations: {{urn:eigenius:demo:patent:key_innovations}}\nApplications: {{urn:eigenius:demo:patent:practical_applications}}";
        completion:system_prompt = "You are a technical writer who explains complex patents in clear, accessible language. Avoid jargon. Focus on why the invention matters and what problems it solves.";
        completion:request_parameters = {
            request:model = "claude-sonnet-4-6";
            request:temperature = 0.3;
            request:max_tokens = 1000;
        };
    };
    Construct patent:PatentBrief {
        patent:summary = summary,
        patent:analysis = analysis
    }
}

// All resources in the patent namespace, regardless of class.
// `MATCH ?r {}` binds ?r to every resource in scope; the WHERE filters
// by IRI prefix using SQL-style LIKE (% matches any sequence).

MATCH ?r {}
WHERE ?r LIKE "urn:eigenius:demo:patent:%"
RETURN [] {
    iri: ?r
}
ORDER BY ?r

// The patent input as an ESL resource declaration. Loading this
// commits a layer with the instance — the next cell (program-run)
// invokes analyze_patent against it by IRI.

namespace patent = "urn:eigenius:demo:patent";

resource patent:US10452978B2 : patent:PatentClaim {
    patent:title = "Attention-based sequence transduction neural networks";
    patent:patent_number = "US10452978B2";
    patent:assignee = "Google LLC";
    patent:filing_date = "2018-06-28";
    patent:abstract_text = "Methods, systems, and apparatus, including computer programs encoded on a computer storage medium, for generating an output sequence from an input sequence. In one aspect, one of the systems includes an encoder neural network configured to receive the input sequence and generate encoded representations of the network inputs, the encoder neural network comprising a sequence of one or more encoder subnetworks, each encoder subnetwork configured to receive a respective encoder subnetwork input for each of the input positions and to generate a respective subnetwork output for each of the input positions, and each encoder subnetwork comprising: an encoder self-attention sub-layer that is configured to receive the subnetwork input for each of the input positions and, for each particular input position in the input order: apply an attention mechanism over the encoder subnetwork inputs using one or more queries derived from the encoder subnetwork input at the particular input position. This is the patent corresponding to the seminal 'Attention Is All You Need' paper by Vaswani, Shazeer, Parmar, Uszkoreit, Jones, Gomez, Kaiser, and Polosukhin (2017), which introduced the Transformer architecture that underlies modern large language models including GPT, BERT, PaLM, and Claude.";
}

// Layer-stack visualisation (D22 §6.9). The auto-renderer detects
// the LayerTopologyResponse shape and dispatches to LayerStackView,
// which draws a vertical stack head→root with per-kind counts on
// each layer. Run this after the cells above so the patent ontology
// + loaded resources are visible in the chain.

return await eigen.layerTopology({ includeResources: false });
